 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);c=b.new_context(viewport={'width':1600,'height':1100},record_har_path=str(out/'network.har'));page=c.new_page();page.on('console',lambda m:r['console'].append({'type':m.type,'text':m.text}));page.on('pageerror',lambda e:r['errors'].append(str(e)));page.on('requestfailed',lambda e:r['failed'].append({'url':e.url,'error':e.failure}));page.goto('http://127.0.0.1:8009');page.wait_for_function('!!window.ageOfAsh');r['manifest']=c.request.get('http://127.0.0.1:8009/__qa_build.json').json();assert r['manifest']['commit']=='7155e1df34be444e1e0b8eb4e7c449916f331104' and not r['manifest']['dirty'];page.locator('#setup-civ').select_option('TEU');page.locator('#btn-start').click();page.evaluate("()=>{const g=ageOfAsh.game;g.setSelection([]);g.units=[];g.buildings=[];g.hero=null;g.crowd=null;g.world.resources=[];g.world.props=[];g.world.wildlife=[];for(const t of g.world.tiles)t.terrain='grass';g.phase='prep';g.prepTimer=1e6;g.autoEconomy=false;g.autoMilitary=false;g.addBuilding('core',10,10,true);window.producer=g.addBuilding('barracks',15,15,true);g.camera={x:0,y:800,targetX:0,targetY:800,zoom:.8,targetZoom:.8};ageOfAsh.renderer.terrainKey='';g.setSelection([producer]);g.stats.trained=0;}");page.locator('[data-command="train:militia"]').click();paid=page.evaluate('()=>({...ageOfAsh.game.resources})');page.evaluate("()=>{for(const t of ageOfAsh.game.world.tiles)t.terrain='water';ageOfAsh.renderer.terrainKey='';}");page.wait_for_function('producer.queue.length===1&&producer.queue[0].remaining===0',timeout=14000);page.wait_for_timeout(300);r['blocked']=page.evaluate("()=>({remaining:producer.queue[0].remaining,trained:ageOfAsh.game.stats.trained,queue:producer.queue.length,resources:{...ageOfAsh.game.resources},label:document.querySelector('#selection-sub').textContent})");assert r['blocked']['remaining']==0 and r['blocked']['trained']==0 and r['blocked']['resources']==paid and 'Waiting'